package app.kivo.store;
import org.json.*;import java.util.*;import java.io.*;
/** Ratings are independent of GitHub stars; identity comes from GitHub, never from the body. */
final class ReviewPolicy {
 static String body(String pkg,int rating,String text)throws Exception{if((pkg==null||!pkg.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))||rating<1||rating>5||text==null||text.trim().length()>2000)throw new IOException("Elige de 1 a 5 y escribe hasta 2,000 caracteres.");return new JSONObject().put("kind","kivo-review-v1").put("package",pkg).put("rating",rating).put("text",text.trim()).toString();}
 static JSONObject aggregate(JSONArray comments,String pkg)throws Exception{Map<String,JSONObject> latest=new LinkedHashMap<>();for(int i=0;i<comments.length();i++)try{JSONObject c=comments.getJSONObject(i),u=c.getJSONObject("user"),b=new JSONObject(c.getString("body"));String login=u.getString("login");int rating=b.getInt("rating");if(!(b.opt("rating") instanceof Number)||b.getDouble("rating")!=rating)continue;if(!b.optString("kind").equals("kivo-review-v1")||!pkg.equals(b.optString("package"))||rating<1||rating>5||b.optString("text").length()>2000||!"User".equals(u.optString("type","User")))continue;JSONObject row=new JSONObject().put("id",c.getLong("id")).put("login",login).put("rating",rating).put("text",b.optString("text")).put("updated",c.optString("updated_at"));JSONObject old=latest.get(login.toLowerCase(Locale.ROOT));if(old==null||row.optString("updated").compareTo(old.optString("updated"))>=0)latest.put(login.toLowerCase(Locale.ROOT),row);}catch(Exception ignored){}
 List<JSONObject> rows=new ArrayList<>(latest.values());Collections.sort(rows,(a,b)->b.optString("updated").compareTo(a.optString("updated")));JSONArray list=new JSONArray();double sum=0;for(JSONObject row:rows){list.put(row);sum+=row.getInt("rating");}return new JSONObject().put("count",rows.size()).put("average",rows.isEmpty()?0:sum/rows.size()).put("reviews",list);}
}
